// 英語の文の表（events_mine）。key は日本語の表（src/i18n/ja/events_mine.js）と同じ。無い key は日本語が出る
// 差し込み {name} は日本語と同じ名前を残す。数の言い分けは {n, plural, one {…} other {…}}（core/i18n.js）
(function (R) {
  'use strict';
  R.I18n.add('en', {
    // ---- src/events/mine_00_common.js
    'ev.mine_00_common.OATH_WORN': '"...fire... god... swear.\n  ...Seventh... shall not...\n  ...our... as far as..."',
    'ev.mine_00_common.OATH_FULL': '"By the god who gave us fire, we swear:\n  we shall not dig below the Seventh Level,\n  as far as our hammers reach."',
    'ev.mine_00_common.SONG': ['♪　By the god who gave us fire, we swear,\nWe dig not below the Seventh Level', '♪　Sleep now, Iron Warden, sleep,\nAs far as our song can reach'],
    'ev.mine_00_common.skyLine.ret': 'Lately the sky you see from the mine\nmouth looks a little pale.\nOr maybe it\'s just me.',
    'ev.mine_00_common.skyLine.ret_2': 'The forge fire\'s weak, but the dark\noutside isn\'t as heavy as it was.\nStrange year.',
    'ev.mine_00_common.skyLine.ret_3': 'Word is the light came back in some\ntown or other. Wish it\'d come back\nto our forge, too.',
    'ev.mine_00_common.lz.say': 'An old letter, its seal unbroken.\nOnly the name is legible: "To Mira."\n...You don\'t feel ready to open it yet.',
    'leads.l_mine_trapped.title': 'Trapped Miners',
    'leads.l_mine_trapped.text': 'A tunnel dug below the Seventh Level\ncaved in. Three miners are trapped\ndeep inside the Deep Shafts.',
    'leads.l_mine_trapped.from': 'Mine Lookout',
    'leads.l_mine_trapped.dir': 'Back of Town',
    'leads.l_mine_guild.title': 'The Guild\'s Side',
    'leads.l_mine_guild.text': 'Without digging the lower veins, the\ntown won\'t survive the winter. So\nsays Mine Chief Borg, at the Guild office.',
    'leads.l_mine_guild.from': 'Mine Chief Borg',
    'leads.l_mine_smiths.title': 'The Smiths\' Side',
    'leads.l_mine_smiths.text': 'Keep the oath to the Smith God and\nseal off what lies below the Seventh\nLevel. So says Helga, at the forge.',
    'leads.l_mine_smiths.from': 'Helga the Blacksmith',
    'leads.l_mine_stone.title': 'The Oath Stone',
    'leads.l_mine_stone.text': 'Half the letters on the Oath Stone at\nthe back of town are gone. An old\ncopy might make it readable.',
    'leads.l_mine_stone.from': 'The Oath Stone',
    'leads.l_mine_door.title': 'The Seventh Level\'s Stone Door',
    'leads.l_mine_door.text': 'Behind the stone door, the Iron Warden\nis stirring awake. Go back to town and\ndecide what to do at the Meeting Hall.',
    'leads.l_mine_door.from': 'Seventh Level',
    'leads.l_mine_seven.title': 'To the Seventh Level',
    'leads.l_mine_seven.text': 'All three trapped miners are home.\nPip\'s Hammer of Oaths is said to open\nthe stone door on the Seventh Level.',
    'leads.l_mine_seven.from': 'Pip the Apprentice',
    'leads.l_mine_seven.dir': 'Seventh Level',
    'leads.l_mine_warden.title': 'The Iron Warden',
    'leads.l_mine_warden.text': 'The town has chosen its path. Open\nthe Seventh Level\'s stone door with\nthe Hammer of Oaths and face the Warden.',
    'leads.l_mine_warden.from': 'Meeting Hall',
    'leads.l_mine_warden.dir': 'Seventh Level',
    'leads.l_main_recorder_mine.title': 'The Rubbing Receipt',
    'leads.l_main_recorder_mine.text': 'Last year the Archive took a rubbing\nof the Oath Stone. The receipt is\nsigned "Rowell."',
    'leads.l_main_recorder_mine.from': 'The Forge Wall',
    'leads.q_mine_lamps.title': '[Keep the Light] Miners\' Lanterns',
    'leads.q_mine_lamps.text': 'Fill the old lanterns at the rest stops\nin the Deep Shafts with oil. Three in all.\nWhile lit, no monsters come near.',
    'leads.q_mine_lamps.from': 'Tadeo the Oil Seller',
    'leads.q_mine_kitten.title': 'The Kitten in the Rockfall',
    'leads.q_mine_kitten.text': 'A kitten went missing in the mine.\nSomeone heard mewing near a narrow\ncrack on the first floor.',
    'leads.q_mine_kitten.from': 'Child in the Square',
    'leads.q_mine_bellows.title': 'Stoking the Forge',
    'leads.q_mine_bellows.text': 'The forge apprentice can\'t work the\nbellows at a steady pace. Take a turn\npumping them for him.',
    'leads.q_mine_bellows.from': 'Forge Apprentice',
    'leads.q_mine_ghost.title': 'The Mine Ghost',
    'leads.q_mine_ghost.text': 'The ghost of an old miner haunts the\nrest stop on the mine\'s second floor.\nHear him out, and he\'ll tell you something.',
    'leads.q_mine_ghost.from': 'Old Miner at the Tavern',
    'leads.l_opt_hermit.title': 'The Mountain Hermit\'s Hut',
    'leads.l_opt_hermit.text': 'On the ridge above the Mine Cart Cliffs\nstands an old hut. The hermit who\nlives there loves to pose riddles.',
    'leads.l_opt_hermit.from': 'Guest at the Inn',
    'leads.l_opt_hermit.dir': 'East',
    'lore.lo_ev_mine.title': 'The Rubbing Receipt',
    'lore.lo_ev_mine.text': 'A receipt stamped with the Archive\'s seal.\n"Received: one rubbing of the Oath Stone.\nCopied for safekeeping.\nRowell, Recorder of the Archive"\nDated last autumn. The stone\'s letters began to vanish soon after.',
    'lore.lo_time_mine.title': 'The Miners\' Shift Roster',
    'lore.lo_time_mine.text': 'An old shift roster at a mine rest stop.\nThe top column reads "Sunrise Watch": the one who went up top to watch for sunrise and call the change of shift.\nThe names stop on the eve of the winter solstice, Lumen Year 292.\nFrom the next day on, the column has been rewritten as "First Bell."',
    'lore.lo_war_mine.title': 'The Arms Ledger',
    'lore.lo_war_mine.text': 'An old Miners\' Guild ledger, covering a few years, twenty years ago.\nSwords, spears, armor, arrowheads. In the buyer column, towns of the Sun Alliance and the Firebird Alliance alternate, line after line.\nThe wealth of the town under the earth stands on this ledger.',
    'lore.lo_mine_oath.title': 'The Smith God\'s Oath',
    'lore.lo_mine_oath.text': 'The Smith God gave people fire, and made them promise one thing:\n"We shall not dig below the Seventh Level."\nThe levels below are white. Dig into the white, they say, and the digger\'s name melts away into it.\nThe one who watches over the oath is the Iron Warden of the Seventh Level.',
    'chronicle.r_mine.title': 'The Smith God\'s Oath',
    'chronicle.r_mine.parts.0.text': 'Deep beneath the Gald Highlands lies Dovan, a town that lives on fire shared from the Smith God\'s Forge.\nThe forge fire weakened, and a tunnel dug below the Seventh Level caved in.',
    'chronicle.r_mine.parts.1.text': '{hero} went down into the Deep Shafts and brought the three trapped miners home.',
    'chronicle.r_mine.parts.2.text': '{hero} opened the Seventh Level with the Guild and struck down the Iron Warden.\nThe lower veins will carry the town through the winter.',
    'chronicle.r_mine.parts.3.text': '{hero} sang the oath song to the Warden with the Smiths.\nThe Warden slept, and the Seventh Level was sealed once more.',
    'chronicle.r_mine.parts.4.text': '{hero} stood between the Guild and the Smiths and swore the oath anew: to dig only the upper veins.\nHearing that oath, the Warden slept.',
    'chronicle.r_mine.parts.5.text': 'Fire returned to the forge, and all the lights of the town beneath the earth brightened at once.',
    'chronicle.r_mine.parts.6.text': 'The people of Dovan remembered the Smith God\'s oath, and will live on, keeping the fire.',
    'chronicle.r_mine.parts.7.text': 'The people of Dovan remembered the Smith God\'s oath.\n...The lights of this town burn atop blades sold to a war. That, too, is set down here.',
    'chronicle.r_mine.parts.8.text': 'The Sunheir claim: "The Smith God forged the sun in his forge. If the forge goes out, so does the sun."',
    'leads.l_opt_volk.title': 'Hammers in the Gorge',
    'leads.l_opt_volk.text': 'Southwest of Ore Valley, where a stream\ndrops into the gorge, there\'s an old\nrope bridge. Below it, they say, hammers\nring and a forge glows red.',
    'leads.l_opt_volk.from': 'Woman in a Dovan Street',
    'leads.l_opt_volk.dir': 'Southwest',
    'leads.l_opt_vein.title': 'The Light Below the Seventh Level',
    'leads.l_opt_vein.text': 'Below even the Seventh Level, they say,\nis a glowing vein no one has ever seen,\nwith a master of its own. Very dangerous.',
    'leads.l_opt_vein.from': 'Dovan Rumor',
    'leads.q_mine_trolley.title': 'The Mine Cart Race',
    'leads.q_mine_trolley.text': 'At Dovan\'s cart station, you can race\ndown the mine rails. Beat the old record\nfor a reward.',
    'leads.q_mine_trolley.from': 'Cart Race Keeper',
    // ---- src/events/mine_dovan.js
    'ev.mine_dovan.BORG.name': 'Borg',
    'ev.mine_dovan.HELGA.name': 'Helga',
    'events.dovan_arrival.caption': 'The town beneath the earth, its forge\nfire restored. Warm light glows\nin every window.',
    'events.dovan_arrival.caption_2': 'Dovan, the Mining City.\nA whole town tucked inside a vast\ncavern in the mountain.',
    'events.dovan_arrival.caption_3': 'The lights are thin, and somehow dim.\nBefore the lift, two groups of men\nglared at each other in silence.',
    'events.dovan_mouth_watch.say': 'Since the Warden fell asleep, the\nair in the mine feels gentler somehow.',
    'events.dovan_mouth_watch.say_2': 'All three came back.\nI owe you more than I can say.',
    'events.dovan_mouth_watch.say_3': 'Past here are the Deep Shafts. A tunnel\ndug below the Seventh Level caved in,\nand three miners are trapped.',
    'events.dovan_mouth_watch.say_4': 'The Guild lot say dig \'em out,\nthe Smiths say it\'s a curse.\nAnd the days go by while they argue.',
    'events.dovan_mouth_watch.say_5': '...You look like you can handle yourself.\nWould you go in and have a look?',
    'events.dovan_mouth_watch.say_6': 'There\'s still {p0} left down there.\nPlease.',
    'events.dovan_mouth_watch.say_7': 'Dag\'s west on the first floor, Rolf\'s\nwhere the water broke through on the\nsecond, and Pip... is at the very bottom.',
    'events.dovan_glare_guild.say': '...What? You on the Smiths\' side?\nIf we don\'t dig the lower levels, this\ntown won\'t make it through winter.',
    'events.dovan_glare_smith.say': 'They broke the oath and dug,\nso the tunnel caved in.\nNo wonder the Warden\'s angry.',
    'events.dovan_after_guild.say': 'The lower vein\'ll see us through this\nwinter. ...Bit lonely with the\nforge shut, mind you.',
    'events.dovan_after_guild.say_2': 'That forge-lighting was something.\nThe Guild will... well, we\'ll scrape\nat the upper levels for a while.',
    'events.dovan_after_guild.say_3': 'How many decades has it been since\nI saw the Guild and the Smiths\ndrinking at the same table?',
    'events.dovan_oath_stone.say': 'The Oath Stone of the Smith God,\ncarved with an anvil and hammer.',
    'events.dovan_oath_stone.say_2': 'Held up against the old copy,\nthe missing letters can be read.',
    'events.dovan_oath_stone.say_3': 'Half the letters aren\'t worn away.\nThey\'re white, as if they had\nnever been there at all.',
    'events.dovan_lift.i.choose': ['Ride', 'Leave'],
    'events.dovan_lift.i.choose.text': 'Take the lift down to the square on the middle tier?',
    'events.dovan_lift.i.choose.text_2': 'Take the lift up to the upper-tier street?',
    'events.dovan_cart_station.say': 'The mine cart station. The rails run\nalong a cliff ledge, all the way to\nthe tunnel at the far east end.',
    'events.dovan_cart_station.say_2': 'A sign hangs here: "Not to be\noperated without Guild permission."',
    'events.dovan_cart_station.i.choose': ['Ride', 'Leave'],
    'events.dovan_cart_station.i.choose.text': 'Ride the mine cart to the end of\nthe line at the Mine Cart Cliffs?',
    'events.dovan_cart_station.caption': 'The cart rattled along the rails\nacross the cliff ledge.',
    'events.dovan_melt_notice.say': 'A new notice on the square\'s board:\n"Blade-Melting Day. The Guild and the\nSmiths together return old blades to the forge."',
    'events.dovan_station_old.say': 'Word is, with the forge back, you\ncan see a glowing vein below the\nSeventh Level. A gem hedgehog\'s nest.',
    'events.dovan_station_old.say_2': 'Rock-eaters burrow under the floor.\nWhen the ground rumbles underfoot,\nbrace yourself and wait.',
    'events.dovan_station_old.say_3': 'And another thing. Below the Seventh\nLevel, there\'s hedgehogs with gems\non their backs. So the old miners said.',
    'events.dovan_station_old.say_4': 'In the old days, someone went up top\nto call the change of shift. What was\nthat job called... I\'ve forgotten.',
    'events.dovan_street_woman.say': 'With the forge fire back, the bread\nbakes lovely. Every oven in town\nburns forge fire, you see.',
    'events.dovan_street_woman.say_2': 'Water\'s broken through on the mine\'s\nsecond floor. Don\'t fall off the planks.\nMonsters won\'t follow you into the water.',
    'events.dovan_hall_old.say': 'The letters on the Oath Stone...\nI feel like they\'re coming back, bit by\nbit. Or maybe it\'s just my old eyes.',
    'events.dovan_hall_old.say_2': 'The town holds its meetings in the\nhall. When there\'s deciding to do,\nGuild and Smiths both gather there.',
    'events.dovan_hall_old.say_3': 'They used to drink at the same table.\nIt was the war, twenty years ago.\nThat\'s when they stopped speaking.',
    'events.dovan_tadeo.say': 'Oil\'s stopped selling.\n...That\'s a good thing, I suppose. Probably.',
    'events.dovan_tadeo.say_2': 'A lantern\'s light is a miner\'s lifeline.\nYou\'ve done them a kindness.',
    'events.dovan_tadeo.say_3': 'All three lit? Let me thank you on\nthe miners\' behalf. Here: a miner\'s\nward-lamp.',
    'events.dovan_tadeo.say_4': '{p0} lanterns to go.\nThe old ones at the mine rest stops.',
    'events.dovan_tadeo.say_5': 'Tadeo, of the Lampkeepers\' Guild.\nOil\'s dear because the Great Beacons\nhave dimmed. Same goes for the forge here.',
    'events.dovan_tadeo.say_6': 'I\'ve a favor to ask. Would you go round\nthe old lanterns at the mine\'s rest stops\nand top them up with this oil? Three of \'em.',
    'events.dovan_tadeo.say_7': 'While they\'re lit, monsters keep away.\nThat\'s what a miners\' rest stop\nis for.',
    'events.dovan_cat_kid.say': 'Mimi, no more going into the mine!\n...Thank you, traveler.',
    'events.dovan_cat_kid.say_2': 'Mimi! Oh, thank goodness...!\nThis is for you. Just a little from\nDad\'s secret stash.',
    'events.dovan_cat_kid.say_3': 'Someone heard mewing by the narrow\ncrack on the mine\'s first floor.',
    'events.dovan_cat_kid.say_4': 'My kitten Mimi rode a mine cart\nright into the tunnels.',
    'events.dovan_cat_kid.say_5': 'The lookout says she\'s mewing by the\ncrack on the first floor.\nPlease, bring her home!',
    'events.dovan_borg.say': 'The lower vein\'ll see the town through\nwinter. ...I owe the Smiths one.\nI\'ll pay them back someday.',
    'events.dovan_borg.say_2': 'We\'ll scrape at the upper levels.\nKeeping an oath makes a man\nhungry, it turns out.',
    'events.dovan_borg.say_3': 'Upper levels only, eh? Your oath,\nthe Guild will keep it too.\nAlongside the Smiths.',
    'events.dovan_borg.say_4': 'It\'s decided, and the Guild will abide.\nGo down to the Seventh Level.\nTo the Warden.',
    'events.dovan_borg.say_5': 'I\'m Borg, Mine Chief.\nI\'m the one who had them dig below\nthe Seventh Level. I\'ll own that.',
    'events.dovan_borg.say_6': 'But without the lower vein, this town\nwon\'t last the winter. The forge fire\'s\nthin, and the upper levels are dug out.',
    'events.dovan_borg.say_7': 'The Smiths go on about oaths and\ncurses, but you can\'t eat an oath.',
    'events.dovan_borg.say_8': 'First, those three trapped men.\nWe\'ll talk after.',
    'events.dovan_borg.say_9': '...The Warden\'s waking, is it?\nThen it\'ll have to go to a town meeting.',
    'events.dovan_borg.say_10': 'Before we decide, two favors for the\nGuild. Go let Dag\'s and Rolf\'s families\nknow they\'re safe.',
    'events.dovan_borg.say_11': 'And have a look at the ledger on the\nback shelf. It\'ll show how many houses\nwon\'t see spring without the lower vein.',
    'events.dovan_borg.say_12': 'You\'ve seen the families and the\nledger. Now it\'s the meeting.\nTo the hall.',
    'events.dovan_borg.say_13': 'The families, and the ledger.\nI\'m counting on you.',
    'events.dovan_borg.say_14': 'All three made it back, eh.\n...I owe you.',
    'events.dovan_borg.say_15': 'Go see what lies behind the\nstone door on the Seventh Level.\nWe\'ll talk after that.',
    'events.dovan_guild_clerk.say': 'Goods from the lower vein are in.\nHave a look at the Guild counter.',
    'events.dovan_guild_clerk.say_2': 'Miners\' tools and medicine are\nat the Guild counter.',
    'events.dovan_ledger.say': 'An old ledger at the back of the shelf,\ncovering a few years, twenty years ago.',
    'events.dovan_ledger.say_2': 'Swords, spears, armor, arrowheads.\nIn the buyer column, towns of the Sun\nand Firebird Alliances alternate.',
    'events.dovan_ledger.say_3': 'There\'s a newer book too. It reads:\n"Houses that cannot last the winter\nwithout the lower vein: thirty-one."',
    'events.dovan_ledger.caption': 'Guild task: You read the ledger.',
    'events.dovan_barkeep.say': 'This is the Guild\'s haunt.\nThe Smiths drink at the forge.\nAnd us all one town.',
    'events.dovan_tav_miner.say': 'Nobody speaks ill of the Warden\nanymore. Turns out it was\nprotecting the town all along.',
    'events.dovan_tav_miner.say_2': 'Word is there\'s a tremendous vein\nsleeping in the lower levels.\nDig it, and the town\'s rich again.',
    'events.dovan_tav_miner.say_3': '...Mind you, they say Pip hasn\'t\nbeen right since he came back\nfrom looking down there.',
    'events.dovan_tav_old.say': 'At the rest stop on the mine\'s second\nfloor, the ghost of an old miner shows\nup. Only on nights the lantern\'s lit.',
    'events.dovan_tav_old.say_2': 'Hear his tale out to the end, and\nhe\'ll tell you something worth\nknowing. Don\'t be scared. Just listen.',
    'events.dovan_tav_old.say_3': 'Twenty years ago, we sold swords\nto both sides. That\'s what made\nthis town rich.',
    'events.dovan_tav_old.say_4': 'In trade, there\'s no friend or foe.\n...The Smiths\' old-timers call\nit a disgrace, though.',
    'ev.mine_dovan.tell.caption': 'Guild task: You told the families they\'re safe.',
    'events.dovan_dag_wife.say': 'I\'d better make his favorite\npotato stew.',
    'events.dovan_dag_wife.say_2': 'He\'s... safe?\nThey\'re tending to him at\nthe Guild office?',
    'events.dovan_dag_wife.say_3': 'Thank you...!\nWhen he gets home, he\'s\ngetting a good scolding.',
    'events.dovan_dag_wife.say_4': 'My husband\'s still trapped\ndeep in the mine.\n...Please, let him be all right.',
    'events.dovan_dag_kid.say': 'Dad\'s coming home?\nYay!',
    'events.dovan_dag_kid.say_2': 'When\'s Dad coming home?',
    'events.dovan_dag.say': 'With the forge fire back, even\nthe mine air is warm.\nI got lucky, I truly did.',
    'events.dovan_dag.say_2': 'You saved me.\nThe wife gave me a right\ngood scolding, though.',
    'events.dovan_rolf_mother.say': 'I\'ve decided I won\'t cry until\nI see my son\'s face.',
    'events.dovan_rolf_mother.say_2': 'Rolf... is alive.\nIn that flooded tunnel, he\nheld on all that time.',
    'events.dovan_rolf_mother.say_3': 'His father was a miner too.\n...Thank you.',
    'events.dovan_rolf_mother.say_4': 'They say my son\'s on the second\nfloor, where the water came in.\nAnd him not able to swim...',
    'events.dovan_rolf.say': 'In the water, I kept my eyes on\nthe light the whole time.\nYour lantern light.',
    'events.dovan_item_keeper.say': 'Welcome!\nIf you\'re headed into the mine, don\'t\nforget your Wakeweed and Antidotes.',
    'events.dovan_inn_keeper.say': 'Welcome!\nWith the forge back, the bathwater\nheats up lovely.',
    'events.dovan_inn_keeper.say_2': 'Welcome!\nWelcome to the Minelamp Inn.',
    'events.dovan_inn_keeper.i.choose': ['Stay', 'Leave'],
    'events.dovan_inn_keeper.i.choose.text': 'Would you like to stay the night?',
    'events.dovan_inn_guest.say': 'There\'s a hut up on the ridge above\nthe Mine Cart Cliffs. The hermit who\nlives there loves a good riddle.',
    'events.dovan_inn_guest.say_2': 'Answer right, and he\'ll give you\nsomething nice, they say.\nHe knows the town\'s old days, too.',
    'events.dovan_helga.say': 'The Smiths are moving to the gorge\nvillage. No hard feelings to the Guild.\n...We\'ll remember the oath.',
    'events.dovan_helga.say_2': 'See the flame at the forge-lighting?\nThat\'s the Smith God\'s fire.\nThe oath is still alive.',
    'events.dovan_helga.say_3': 'Upper levels only, eh? A good oath.\nThe Smiths will sit at the Guild\'s\ntable too.',
    'events.dovan_helga.say_4': 'It\'s decided, isn\'t it?\nGo to the Warden, then.\nTake the Hammer of Oaths.',
    'events.dovan_helga.say_5': 'I\'m Helga, blacksmith.\nWe don\'t dig below the Seventh Level.\nThat\'s our oath to the Smith God.',
    'events.dovan_helga.say_6': 'Seems when the Guild gets hungry,\nthey\'ll eat an oath too.\nThat caved-in tunnel is the proof.',
    'events.dovan_helga.say_7': '...And take a look at the paper on\nthe wall. Last year a young one from\nthe Archive came and took a rubbing.',
    'events.dovan_helga.say_8': 'That\'s when the stone\'s letters\nstarted vanishing, and the forge\nfire began to weaken.',
    'events.dovan_helga.say_9': 'First, go bring those trapped\nlads home. We\'ll talk after.',
    'events.dovan_helga.say_10': 'The Warden\'s waking...\nWe\'ve no choice but to make it\nremember the oath. Lend me a hand.',
    'events.dovan_helga.say_11': 'A hermit lives on the ridge above\nthe Mine Cart Cliffs. He copied the\nstone\'s words when he was young.',
    'events.dovan_helga.say_12': 'And the stone statue of the Smith\nGod in the back here. Read the\nprayer on its pedestal, will you.',
    'events.dovan_helga.say_13': 'The hermit\'s copy? ...Let me see.',
    'events.dovan_helga.say_14': '"As far as our hammers reach."\n...Yes, that\'s how it went.\nEven we\'d half forgotten.',
    'events.dovan_helga.caption': 'Smiths\' task: You checked the stone\'s words.',
    'events.dovan_helga.say_15': 'You\'ve seen the copy and the prayer.\nNow it\'s the meeting. To the hall.',
    'events.dovan_helga.say_16': 'The hermit\'s copy, and the\nstatue\'s prayer. I\'m counting on you.',
    'events.dovan_helga.say_17': 'Dag, Rolf, and Pip...\nthey\'re all home. ...Thank you.',
    'events.dovan_helga.say_18': 'Take Pip\'s hammer and go look\nat the stone door on the Seventh Level.\nSee how the warden fares.',
    'events.dovan_forge_seller.say': 'The Smiths are moving to the gorge\nvillage. We\'re closing up shop.\nThe Guild can borrow the forges we leave.',
    'events.dovan_forge_seller.say_2': 'Good steel, fresh from the\nforge-lighting. Have a look.',
    'events.dovan_forge_seller.say_3': 'The Smiths\' counter.\nHave a look.',
    'events.dovan_receipt.say': 'Pinned to the wall is a receipt\nstamped with the Archive\'s seal.',
    'events.dovan_receipt.caption': '"Received: one rubbing\nof the Oath Stone.\nCopied for safekeeping.\nRowell, Recorder of the Archive"',
    'events.dovan_receipt.say_2': 'Rowell.\nFor a while, {hero} couldn\'t\nlook away from the name.',
    'events.dovan_forge_statue.say': 'A small stone statue of the Smith God.\nA prayer is carved into its pedestal.',
    'events.dovan_forge_statue.say_2': 'The words of the oath song.\nThey say it\'s a song to lull\nthe Warden to sleep.',
    'events.dovan_forge_statue.caption': 'Smiths\' task: You read the statue\'s prayer.',
    'events.dovan_forge_boy.i.choose': ['Go through', 'Leave'],
    'events.dovan_forge_boy.i.choose.text': 'Take the Smiths\' back path\nout to Gald Pass?',
    'events.dovan_forge_boy.caption': 'You climbed the narrow tunnel behind\nthe forge for a long while.',
    'events.dovan_forge_boy.say': 'Steady pace, steady pace...\nI can do it with my eyes shut now!',
    'events.dovan_forge_boy.say_2': 'I can\'t get the bellows right.\nToo fast or too slow, and\nthe fire sulks.',
    'events.dovan_forge_boy.say_3': 'Could you show me how?\nTry pumping the bellows.',
    'events.dovan_bellows.say': 'A huge bellows.\nWith every push, the forge roars.',
    'events.dovan_bellows.r.title': 'Pump the Bellows',
    'events.dovan_bellows.say_2': 'Wow, the forge changed color!\nThis is from Miss Helga.\nFor your trouble, she says.',
    'events.dovan_bellows.say_3': 'So close! Try to keep\na steadier pace.',
    'events.dovan_hall_chair.say': 'I\'ve written your name in the\nmeeting book, as a friend\nof the town.',
    'events.dovan_hall_chair.say_2': 'The town has chosen its path.\nNow for the Warden of the Seventh Level.',
    'events.dovan_hall_chair.say_3': 'I\'m the meeting steward. With the\nGuild and the Smiths glaring like\nthis, I can\'t even call a meeting.',
    'events.dovan_hall_borg.say': 'The ledger\'s closed.\nClosed, but not thrown away.\nSo we remember.',
    'events.dovan_hall_borg.say_2': 'Upper levels only, eh.\n...Not bad.',
    'events.dovan_hall_helga.say': 'Come on Blade-Melting Day.\nYou can feed the first blade\ninto the forge.',
    'events.dovan_hall_helga.say_2': 'The Guild\'s ale is thin.\n...Well, it\'s not bad.',
    'events.dovan_assembly.say_2': 'If you did what both sides asked of\nyou, you might find a path where\nneither loses face, mind.',
    'events.dovan_assembly.labels': ['Side with the Guild (open the Seventh Level)', 'Side with the Smiths (seal the lower levels)'],
    'events.dovan_assembly.labels.0': 'Mediate (dig only the upper levels)',
    'events.dovan_assembly.labels.0_2': 'Not yet',
    'events.dovan_assembly.i.choose.text': 'Decide the town\'s path.',
    'events.dovan_assembly.say_3': 'Come back once you\'ve decided.',
    'events.dovan_assembly.say_4': 'The meeting sided with the Guild.\nThey\'ll open the Seventh Level and\nfight the Warden.',
    'events.dovan_assembly.say_5': 'The Smiths walked out without a word.\n...They do say the Warden only sleeps\nfor the Smiths\' song.',
    'events.dovan_assembly.say_6': 'The meeting sided with the Smiths.\nThey\'ll sing the oath song to the\nWarden and seal the lower levels.',
    'events.dovan_assembly.say_7': 'The Guild lot went home with\ntheir heads hung low. Hungry or not,\nan oath\'s an oath.',
    'events.dovan_assembly.say_8': 'The meeting accepted the mediation.\nThey\'ll swear anew to the Warden\nto dig only the upper veins.',
    'events.dovan_assembly.say_9': 'Twenty years since I\'ve seen the Guild\nand the Smiths sit at the same table.\n...It pays to live long.',
    'events.dovan_assembly.say_10': 'Take the Hammer of Oaths to the\nSeventh Level\'s stone door.\nThe town\'s lights are in your hands.',
    'events.dovan_assembly.gather': 'Let\'s open the meeting.\nThe Guild and the Smiths both say\nthey\'ll hear you out.',
    'events.dovan_assembly.caption': 'The Dovan Assembly',
    'events.dovan_assembly.open': 'Thank you all for coming.\nDo we open the Seventh Level\'s\nstone door, or seal it? Tonight we decide.',
    'events.dovan_assembly.borg': 'Without the lower vein,\nthis town won\'t last the winter.\nOpen the door and beat the Warden.',
    'events.dovan_assembly.borg_2': 'Once it\'s settled, the Guild will\ndig out the old cart-line tunnel\nto the plateau again.',
    'events.dovan_assembly.miner': 'That\'s right! You can\'t keep\nan oath on an empty belly!',
    'events.dovan_assembly.helga': 'We don\'t dig below the Seventh Level.\nThat\'s our oath to the Smith God.\nWe sing the Warden to sleep, and seal it.',
    'events.dovan_assembly.helga_2': 'Seal it, and we\'ll open the Smiths\'\nback path. I\'ll take you to the forge\nat Volk, our village in the valley.',
    'events.dovan_assembly.smith': 'The collapsed tunnels are your answer.\nBreak an oath, and the mountain\nwon\'t stay quiet.',
    'events.dovan_assembly.dag': 'This is the one who brought us back.\n...Let\'s leave it to them\nto decide.',
    'events.dovan_assembly.woman': 'I don\'t care which.\nJust so the children\'s lights\ndon\'t go out.',
    'events.dovan_assembly.accord': 'You heard out both sides.\nMaybe you can see a road\nwhere both can keep their pride.',
    'events.dovan_assembly.r_guild': 'Right, it\'s settled!\nGuild folk, grab your picks!',
    'events.dovan_assembly.r_smiths': '...Thank you.\nWe\'ll keep the oath.',
    'events.dovan_assembly.r_accord': 'Only the upper levels, eh.\n...Helga. Lend me a hand.',
    'events.dovan_assembly.r_accord_2': 'Borg, bowing his head? Well.\n...All right. We\'ll sit at one table.',
    'events.dovan_hall_table.say': 'The assembly\'s ledger lies open.\nOn the newest line\nis written {hero}\'s name.',
    'events.dovan_hall_table.say_2': 'A map of the mine is spread out.\nThe Guild\'s seal and the Smiths\' seal\nglare at each other across it.',
    'events.dovan_hall_table.say_3': 'A map of the mine is spread out.\nThe Seventh Level\'s stone door\nis circled in red.',
    'events.dovan_hall_table.say_guild': 'On the map, a red line runs\nto the Seventh Level.\n"Open," someone has written.',
    'events.dovan_hall_table.say_smiths': 'On the map, a thick ink line\ncrosses the Seventh Level.\n"Sealed below this point."',
    'events.dovan_hall_table.say_accord': 'Above the Seventh Level on the map,\nthe Guild\'s seal and the Smiths\' seal\nsit side by side.',
    'events.dovan_hall_table.i.choose': ['Open the assembly', 'Not now'],
    'events.dovan_hall_table.i.choose.text': 'Gather the townsfolk and\nopen the assembly?',
    'ev.mine_dovan.QUIZ.0.q': 'What did the Smith God make people promise?',
    'ev.mine_dovan.QUIZ.0.a': ['Not to dig below the Seventh Level', 'Never to let the fire die', 'Never to sell iron'],
    'ev.mine_dovan.QUIZ.1.q': 'What was the job called, when old\nminers went up top to call the shift?',
    'ev.mine_dovan.QUIZ.1.a': ['First Bell', 'Sunrise Watch', 'Night Watch'],
    'ev.mine_dovan.QUIZ.2.q': 'What was the war twenty years ago, when towns\nfought over whose light was the true sun?',
    'ev.mine_dovan.QUIZ.2.a': ['The Beacon War', 'The Sunheir War', 'The Bell War'],
    'events.mine_hermit.say': 'Well now, a visitor. That\'s rare.\nUp here, the wind\'s my only\ncompany for talk.',
    'events.mine_hermit.say_2': 'Helga sent you? A copy of the Oath\nStone... I have one. Copied it on\npaper as a lad, long before the Archive.',
    'events.mine_hermit.say_3': 'Copying it on paper didn\'t make the\nstone fade. Only copying into that white\nbook does. ...Strange business, eh?',
    'events.mine_hermit.say_4': 'You\'ve had your prize for the riddles.\nNow I\'ll go back to talking\nwith the wind.',
    'events.mine_hermit.i.choose': ['Take the riddles', 'Leave'],
    'events.mine_hermit.i.choose.text': '"Answer my three questions,\nand I\'ll reward you."',
    'events.mine_hermit.say_5': 'Hmm, not quite.\nGo listen to the town\'s tales,\nthen come back.',
    'events.mine_hermit.say_6': 'Splendid. You\'ve listened well to the\nold tales. Take this. It\'ll help\nyour Sparks along.',
    'events.dovan_street_woman.say_3': 'Under the old rope bridge, southwest\nof the valley, there\'s a village of Smiths\nwho left town. At night you see forge-glow.',
    // ---- src/events/mine_deep.js
    'ev.mine_deep.WARDEN.name': 'Iron Warden',
    'ev.mine_deep.PIP.name': 'Pip',
    'ev.mine_deep.BORG.name': 'Borg',
    'ev.mine_deep.HELGA.name': 'Helga',
    'events.mine_arrive.caption': 'The Deep Shafts.\nThe rails run off into the dark,\nand somewhere, water is falling.',
    'events.mine_cavein.say': 'Collapsed props and rock lie piled up.\nIt\'s a wonder anyone held out\nunder there.',
    'events.mine_cavein.say_2': 'Collapsed props and rock.\nFrom beyond comes a groan.',
    'events.mine_miner1.say': 'Wh-who\'s there...?\nHas help come...?!',
    'events.mine_miner1.say_2': 'His leg is pinned under a fallen\nprop. Together, you heave it up.',
    'events.mine_miner1.say_3': 'You saved me... I\'m Dag, a miner.\nRolf and Pip should still be\nfurther in.',
    'events.mine_miner1.say_4': 'Pip was digging deepest of all,\nbelow the Seventh Level.\n...I can get out on my own.',
    'events.mine_miner1.caption': 'Dragging his leg, Dag headed\nfor the exit.',
    'events.mine_kitten.say': 'Deep in the crack, a kitten mews.\nWhen you reach in, it licks\nyour finger timidly.',
    'events.mine_kitten.caption': 'The kitten follows you. Time to take\nit home to the child in the square.',
    'events.mine_cart_ride.say': 'A narrow rail trestle spans the\nshaft. You can\'t cross on foot.',
    'events.mine_cart_ride.i.choose': ['Ride', 'Leave'],
    'events.mine_cart_ride.i.choose.text': 'Ride the mine cart across the shaft?',
    'events.mine_cart_ride.caption': 'The cart rattled across,\nover the darkness.',
    'events.mine_lamp.say': 'The lantern burns warmly.',
    'events.mine_lamp.say_2': 'An old miner\'s lantern.\nIts oil is spent, and it\'s gone cold.',
    'events.mine_lamp.say_3': 'You filled the lantern with miner\'s lamp oil.',
    'events.mine_lamp.caption': 'The miner\'s lantern is lit. ({n}/3)',
    'events.mine_lamp.caption_2': 'The oil is used up. Time to tell Tadeo in town.',
    'events.mine_f2_arrive.caption': 'The mine\'s second floor.\nA damp wind flows in from the west.',
    'events.mine_miner2.say': '...A light.\nA real light...!',
    'events.mine_miner2.say_2': 'Rolf, miner. The water came in and\nI couldn\'t move from here. The plank\nwalkway got washed out halfway, too.',
    'events.mine_miner2.say_3': 'I\'ll rest a bit under the old lantern\nat the rest stop, then head back.\nThat\'s always been a miners\' spot.',
    'events.mine_miner2.caption': 'Rolf edged his way back\nalong the plank walkway.',
    'events.mine_shift_board.say': 'An old shift roster.\nThe top column reads "Sunrise Watch."',
    'events.mine_shift_board.say_2': 'Small writing beside the column:\n"Goes up top to watch for sunrise\nand call the change of shift."',
    'events.mine_shift_board.say_3': 'The names stop on the eve of the\nwinter solstice, Lumen Year 292. From the\nnext day, the column reads "First Bell."',
    'events.mine_rest_bench.say': 'A long bench worn smooth by\nresting miners. Sitting on it, your\nback feels just a little warm.',
    'events.mine_lz.say': 'Nothing is tucked under the\nold lantern anymore.',
    'events.mine_lz.say_2': 'Tucked under the old lantern on the\nwall is an envelope, sealed with\nthe Archive\'s seal.',
    'events.mine_lz.say_3': 'Last year a Recorder rested here,\nthen fled in a hurry, it seems.\n...He must have left it behind.',
    'events.mine_ghost.say': 'Well, now. Was it you who gave me\nthis light? Thank you kindly.\n...Will you sit a while?',
    'events.mine_ghost.say_2': 'I was the Sunrise Watch.\nEvery morning I\'d go up top\nand watch for the sun to rise.',
    'events.mine_ghost.say_3': 'When the sun came up, I rang the\nbell to call the change of shift\nfor all below. That was my job.',
    'events.mine_ghost.say_4': 'One night... the night before\nthe winter solstice. I went up top\nand waited, but the sun never rose.',
    'events.mine_ghost.say_5': 'I waited and waited. It never came.\nI grew tired of waiting,\nand fell asleep right here.',
    'events.mine_ghost.caption': 'The old miner faded away,\nas if melting into the lantern light.',
    'events.mine_ghost.say_6': '...As thanks for listening.\nBeside the tunnel that leads down,\nI hid my toolbox.',
    'events.mine_rockeater.say': 'The floor of the side tunnel cracked\napart. A giant rock-gnawing worm\nreared its head.',
    'events.mine_rockeater.say_2': 'The Rock Eater crumbled.\nFrom deep in the side tunnel,\na faint voice can be heard.',
    'events.mine_pip.say': '...Wh-who\'s there?\nD-did you beat that worm...?',
    'events.mine_pip.say_2': 'I\'m Pip, an apprentice.\nThe one who dug deepest below\nthe Seventh Level... that was me.',
    'events.mine_pip.say_3': 'I... looked down there.\nIt was white. There was no sound.',
    'events.mine_pip.say_4': 'When I looked down, for a moment...\nI couldn\'t remember my own name.',
    'events.mine_pip.say_5': '...This is the Hammer of Oaths.\nMiss Helga gave it to me. It opens\nthe stone door of the Seventh Level.',
    'events.mine_pip.say_6': 'I don\'t want to dig anymore.\n...But I don\'t want the town to starve\neither. What should I do?',
    'events.mine_pip.caption': 'Looking back again and again,\nPip headed for the exit.',
    'events.mine_f3_arrive.caption': 'The Seventh Level.\nLight is swallowed by the dark.\nBetter light the candle stands.',
    'events.mine_rockdoor.say': 'The stone door of the Seventh Level:\ntwo huge slabs of rock carved\nwith an anvil and hammer.',
    'events.mine_rockdoor.say_2': 'It won\'t budge an inch.\nThere must be a tool that fits.',
    'events.mine_rockdoor.say_3': 'With the Hammer of Oaths, you struck\nthe anvil mark on the stone door.',
    'events.mine_rockdoor.say_4': 'A thin gap opened in the door.\nBeyond the hall, further down,\na rift in the floor... is white.',
    'events.mine_rockdoor.say_5': 'White. Soundless.\nLooking at it, you almost forget\nhow to breathe.',
    'events.mine_rockdoor.say_6': '...You who forgot the oath.\nYou who dug below the Seventh Level.',
    'events.mine_rockdoor.say_7': 'Deep within, iron creaked.\nThe Warden is stirring awake.\n...The stone door closed again.',
    'events.mine_rockdoor.say_8': 'You\'ll have to go back to town\nand decide what to do.',
    'events.mine_rockdoor.say_9': 'Behind the stone door, the Warden\'s\npresence sits heavy and still.\nLet the town meeting choose the path.',
    'events.mine_rockdoor.say_10': 'With the Hammer of Oaths, you struck\nthe anvil mark once more.',
    'events.mine_rockdoor.caption': 'The stone door of the Seventh Level\nslowly swung open.',
    'events.mine_guardian_throne.say': 'The fallen Iron Warden.\nOnly its great hammer remains,\npropped against the throne.',
    'events.mine_guardian_throne.say_2': 'The Iron Warden sleeps upon its throne.\nDeep in its chest, a red glow like forge\nfire pulses quietly.',
    'events.mine_guardian_throne.say_3': 'An iron giant upon a throne.\nBehind its lowered helm,\na red light flickers.',
    'events.mine_breach.say': 'A rift in the floor.\nNo rock, no darkness. Only white.\nNo bottom, and no end.',
    'events.mine_breach.say_2': 'As you peer in, your own name\nbegins to drift away.\n...{hero} looked away.',
    'events.mine_warden.say': 'The iron giant on the throne\nraised its helm.\nIts great hammer rang on the floor.',
    'events.mine_warden.say_2': 'By my pact with the Smith God,\nI guard this mountain.\nDepart, or be broken.',
    'events.mine_warden.say_3': 'The Iron Warden sank to its knees\nand slowly crumbled.',
    'events.mine_warden.say_4': '...So my task, too, is ended.\nThe creak of iron seemed\nto say as much.',
    'events.mine_warden.say_5': '{hero} set the prayer from the Smith\nGod\'s statue to song, and sang it\nto the Warden.',
    'events.mine_warden.say_6': '{hero} stepped before the Warden\nto speak the oaths of the Guild\nand the Smiths as one.',
    'events.mine_warden.q.choose': ['We will dig only the upper veins', 'We will not touch what lies below the Seventh Level', 'We will not give the town\'s names to the white dark'],
    'events.mine_warden.q.choose.text': 'What will you swear to the Warden?',
    'events.mine_warden.say_7': ['"We will dig only the upper veins."\nThe light behind the Warden\'s helm\nflickered once, slowly.', '"We will not touch what lies below the\nSeventh Level." The Warden\'s great\nhammer lifted slightly from the floor.', '"We will not give the town\'s names to the\nwhite dark." Deep in the Warden\'s chest,\na red light like a forge kindled.'],
    'events.mine_warden.say_8': '...So the oath still lives.\nThen I shall sleep.',
    'events.mine_warden.say_9': 'The Warden laid its hammer across\nits knees and quietly fell asleep.',
    'events.mine_relight.caption': 'Somewhere beyond the Seventh Level,\nsomething drew a great breath.',
    'events.mine_relight.caption_2': 'Fire returned to the Smith God\'s Forge.',
    'events.mine_relight.caption_3': 'All at once, the lights of the town\nbeneath the earth grew bright.',
    'events.mine_relight.say': '...Look. It\'s the forge fire.\nIt\'s filling every window.',
    'events.mine_relight.say_2': 'The stone\'s letters... they\'re back.\n"As far as our hammers reach."',
    'events.mine_relight.say_3': '...My name is Pip.\nI remember it. I really do.',
    'events.mine_finale.say': 'The Guild wins. We\'ll drink to it.\n...Helga, what about your lot?',
    'events.mine_finale.say_2': 'The Smiths are moving to the gorge\nvillage. Can\'t swing a hammer on\na mountain with no Warden.',
    'events.mine_finale.say_3': 'Time to light the forge.\nWe get first share of the fire\nfrom the Smith God\'s Forge.',
    'events.mine_finale.say_4': '...The Guild will dig the upper levels.\nWe\'ll go hungry, but it beats\nlosing our names.',
    'events.mine_finale.say_5': 'Tonight at the Guild tavern, I\'m\nbuying the Smiths a round too.\n...At the same table.',
    'events.mine_finale.say_6': 'The Guild\'s ale is thin, mind.\n...Not bad, though.',
    'events.mine_finale.say_7': 'And this is the town\'s thanks.\nThe Oath Bracelet.\nYou made us remember the oath.',
    'events.mine_finale.say_8': 'Have a look at the receipt on the\nforge wall. It has the name of that\nyoung one from the Archive on it.',
    'events.mine_finale.say_9': 'There\'s an old shift roster at the\nmine rest stop. The top column\nsays "Sunrise Watch," you know.',
    'events.mine_finale.i.choose': ['Write it as the tale of the oath', 'Also write of the ledger: arms sold to both sides'],
    'events.mine_finale.i.choose.text': 'What will you write in the Chronicle?',
    'events.mine_finale.say_10': '{hero} wrote of the ledger too:\nhow twenty years ago, this town\nsold blades to both sides.',
    'events.mine_finale.say_11': '...You\'ll write it.\nI see. ...Aye, you should.',
    'events.mine_finale.caption': 'That night, at a table in the hall,\nBorg and Helga closed the same ledger.',
    'events.mine_finale.say_12': 'We\'ve put up a notice in the square:\n"Blade-Melting Day." The old blades\ngo back to the forge.',
    'events.mine_finale.say_13': '{hero} wrote it in the Chronicle\nas the tale of the Smith God\'s oath.',
    'events.mine_finale.say_14': 'The Smith God forged the sun in\nhis forge. If the forge goes out, so\ndoes the sun. ...So Grandpa used to say.',
    // ---- src/events/mine_field.js
    'events.mine_pass_cairn.say': 'A cairn of piled stones. On a rusted\niron plate: "To Dovan, follow\nthe sound of hammers."',
    'events.mine_pass_cairn.say_2': 'You listen closely. From across the\nvalley, you can hear hammers.',
    'events.mine_pass_tunnel.say': 'The mouth of an old tunnel, boarded\nshut. Through the gaps comes a faint\nsmell of hot iron.',
    'events.mine_pass_tunnel.say_2': 'Carved here: "The Smiths\' back path.\nNo passage without leave."',
    'events.mine_gate_guard.say': 'See the town light leaking through\nthe gate? The forge is back.',
    'events.mine_gate_guard.say_2': 'This is the gate to Dovan, the Mining\nCity. The town\'s inside the mountain,\nat the bottom of a cavern.',
    'events.mine_gate_guard.say_3': '...Things are tense in there just now.\nThe Guild and the Smiths are at each\nother\'s throats. A tunnel caved in.',
    'events.mine_sorting_shed.say': 'The ore-sorting shed. Gray ore sits\npiled on the tables. With the forge\nfire low, no one\'s left to sort it.',
    'events.mine_cliff_lift.say': 'A cliff lift. The winch rope has\nsnapped, and the cage dangles in\nthe darkness below.',
    'events.mine_rail_tunnel.say': 'An old cart-line tunnel leading to\nthe plateau, blocked by a fence\nof heavy timbers.',
    'events.mine_rail_tunnel.say_2': 'A sign hangs here: "Closed due\nto rockfall. -- The Guild"',
    'events.mine_rail_tunnel.say_3': 'If the Guild ever digs it out,\nit\'ll be after the mountain\'s\ntrouble is settled.',
    'events.mine_rail_tunnel.say_4': 'The Guild seems busy enough\nworking the upper levels now.',
    'events.mine_rail_tunnel.i.choose': ['Ride', 'Leave'],
    'events.mine_rail_tunnel.i.choose.text': 'Ride the mine cart back to\nDovan\'s station?',
    'events.mine_rail_tunnel.caption': 'The cart rattled along the rails toward town.',
    'events.mine_rail_tunnel.i2.choose': ['To the plateau', 'To Dovan', 'Leave'],
    'events.mine_rail_tunnel.i2.choose.text': 'The fence is gone, and the rails run\nall the way through the tunnel.\nWhere will you ride the cart?',
    'events.mine_rail_tunnel.caption_2': 'The cart passed through the mountain\'s\nbelly and came out below the Stargazer\'s Slope.',
    'events.star_rail_stop.say': 'The end of the old cart line. The rails\nvanish into a tunnel under the cliff,\nblocked further in by a rockfall.',
    'events.star_rail_stop.say_2': 'The sign on the buffer stop reads:\n"To Dovan. -- The Guild"',
    'events.star_rail_stop.i.choose': ['To Dovan', 'To the Mine Cart Cliffs', 'Leave'],
    'events.star_rail_stop.i.choose.text': 'The end of the cart line.\nWhere will you ride the cart?',
    'events.star_rail_stop.caption': 'The cart passed through the mountain\'s\nbelly and came out on the cliff ledge.',
    // ---- src/events/mine_volk.js
    'events.volk_arrive.caption': 'At the bottom of the gorge ring the\nsound of the falls and the sound\nof hammers.',
    'events.volk_arrive.caption_2': 'Volk, the Smiths\' Hidden Village',
    'events.volk_bridge_old.say': 'So Helga and her lot finally came down\nhere. Handed the town forge to the Guild.\n...This forge burns better anyway.',
    'events.volk_bridge_old.say_2': 'The seal on the stone steps is lifted.\nThe young ones from Dovan come down\nnear every day. Lively, it\'s become.',
    'events.volk_bridge_old.say_3': 'The Guild lads haul ore down here.\nFirst time in twenty years the town\nand the village beat the same iron.',
    'events.volk_bridge_old.say_4': ['...A stranger, eh?\nNot many cross this\nrope bridge.', 'This is the village of the Smiths.\nOnly those who keep the oath, that\nblades are forged to protect, live here.'],
    'events.volk_yard_smith.say': 'Since the forge fire came back,\nthe iron\'s a different color. Maybe the\nSmith God himself has woken up.',
    'events.volk_yard_smith.say_2': 'The water wheel works the bellows.\nThanks to it, the fire here never\ngoes out, all night long.',
    'events.volk_child.say': 'Hey, do you know about the cart race\nin Dovan? Ask the man at the station,\nand he\'ll let anybody ride!',
    'events.volk_child.say_2': 'They say the Smith God\'s anvil\nis hidden behind the waterfall.',
    'events.volk_pip.say': ['It\'s just down the stone steps.\nThe old Smiths are teaching me\nhow to work the hammer.', '...I can say my name just fine.\nPip. Yeah. I\'m all right.'],
    'events.volk_trader.say': 'Iron from the upper veins.\nThe Guild digs, the village forges.\nMaster Borg\'s idea.',
    'events.volk_apprentice.say': 'I followed Master Helga here.\nWe gave the town forge to the Guild.\nBut... the forge here is amazing!',
    'events.volk_shrine.say': 'A small statue of the Smith God.\nThe iron nails left as offerings\nglow red in the forge light.',
    'events.volk_shrine.say_2': ['A small statue of the Smith God.\nThe oath is carved on its pedestal.', '"Forge blades to protect.\n  Dig not below the Seventh Level."'],
    'events.volk_shrine.caption': '{hero} pressed their hands together\nbefore the statue.',
    'events.volk_wheel.say': 'A great water wheel turns, thump,\nthump, sending air to the forge\'s bellows.',
    'events.volk_anvil.say': 'The yard\'s anvil, so well used\nit\'s worn hollow in the middle.',
    'events.volk_anvil.say_2': ['You struck the anvil with the hammer\nbeside it. A clear clang rang\nthrough the gorge.', '...Under the anvil, a whetstone\nwrapped in cloth was tucked away.'],
    'events.volk_stair.say': ['Old stone steps climbing the cliff,\nsealed with a tag bearing the\nSmiths\' mark.', '"These steps lead to Dovan.\n  Closed until the day the oath\n  returns to the town."'],
    'events.dovan_volkpath.say': ['Through a crack in the cliff, old stone\nsteps lead down, sealed with a tag\nbearing the Smiths\' mark.', 'From far below, you think you\ncan hear hammers, faintly.'],
    'events.volk_innkeep.say': 'Nothing like falling asleep to the\nsound of the falls. Staying the night?',
    'events.volk_innkeep.say_2': 'If the falls don\'t bother you, you\'ll\nsleep sound. Staying the night?',
    'events.volk_innkeep.i.choose': ['Stay', 'Not now'],
    'events.volk_innkeep.i.choose.text': 'Stay at the inn?',
    'events.volk_guest.say': ['I came to soak in the gorge springs,\nbut the villagers say there\'s a glowing\nvein way down below Dovan\'s mines.', 'Further down than the Seventh Level,\nwith a master of its own, they say.\nHeaven preserve us.'],
    'events.volk_master.say': ['Ilsa, master of the Great Forge.\nEvery blade here is forged one by one.\nYou\'ll never see the same one twice.', 'You\'re free to buy.\nBut there are no blades here to sell\nto a war. Remember that.'],
    'events.volk_master.say_2': 'We can come and go with the town\'s\nSmiths again. Good iron\'s been coming in.',
    'events.volk_master.say_3': 'What\'ll you look at today?',
    'events.volk_helga.say': ['...We\'ve lent the town forge to\nthe Guild. The Smiths forge here now.', 'It\'s the path you all chose.\nNo hard feelings. But we\'ll go on\nsinging the oath song here.'],
    'events.volk_dovan_seller.say': 'Hauled every last piece from the\ntown counter down here.\nHave a look.',
    'events.volk_forge_stone.say': ['The Smith God\'s stone: a small copy\nof the Oath Stone. Not a letter missing.', '"Forge blades to protect.\n  Dig not below the Seventh Level.\n  Share the fire and the iron."'],
    'events.volk_wife.say': 'My husband\'s so glad he can talk\nwith the town\'s Smiths again.',
    'events.volk_wife.say_2': 'The townsfolk call us the smiths\nwho ran off, don\'t they? ...We didn\'t\nrun. We stayed. True to the oath.',
    'events.volk_gunnar.say': ['Twenty years ago, Dovan sold blades\nto both sides of the war. That\'s\nhow the town grew rich.', 'We didn\'t sell. Blades are forged\nto protect. That\'s our oath to\nthe Smith God.', 'So we left the town and built a\nforge in this gorge. ...We did nothing\nto be ashamed of. Nor anything to boast of.'],
    'events.volk_gunnar.say_2': 'Helga came. Twenty years on, the\nsame thing happened again. ...But this\ntime, nobody has sold a blade.',
    'events.volk_gunnar.say_3': 'The townsfolk hum the oath song again.\nIt pays to live long.',
    'events.volk_gunnar.say_4': 'In town, I hear the Guild and the\nSmiths are glaring at each other.\n...Fire is a thing to be shared.',
    'events.volk_elder_book.say': ['An old ledger listing the names of\nforged blades and who received them.', 'Every entry in the recipient column\nreads "village guard" or "traveler\'s\nescort." Not one names a side in a war.'],
    // ---- src/events/mine_vein.js
    'events.mine_vein_shaft.say': ['A crack in the rock at the corner of\nthe hall. From far below, blue light\nflickers upward.', 'There\'s no rope ladder going down.\nIf the Guild comes to dig,\nthey\'ll hang one someday.'],
    'events.vein_arrive.caption': 'Veins of blue light run through every rock.',
    'events.vein_arrive.caption_2': 'The Abyssal Vein, which no eye has yet seen.',
    'events.vein_f2_arrive.caption': 'On a still underground lake,\nthe light of crystals is reflected.',
    'events.vein_f3_arrive.caption': 'From deep within comes a ringing...\nthe sound of crystals singing.',
    'events.vein_cart_ride.say': 'An old mine cart sits at the end of\nthe rails. The trestle is narrow;\nyou can\'t cross on foot.',
    'events.vein_cart_ride.i.choose': ['Ride', 'Not now'],
    'events.vein_cart_ride.i.choose.text': 'Ride the cart across the chasm?',
    'events.vein_cart_ride.caption': 'Clunk, clunk...\nThe cart rolls across the glowing chasm.',
    'events.vein_nest_note.say': ['A note carved in the rock by a miner of old.', '"Many hedgehogs with gem backs in this cave.\n  One back-stone feeds you for a month.\n  But they are quick."'],
    'events.vein_heart.say': ['A glowing vein fills the whole north wall.\nIts pulsing light is quiet now.', '...Dig not below the Seventh Level.\nYou feel you understand that oath\na little better now.'],
    'events.vein_heart.say_2': 'A glowing vein fills the whole north wall.\nJust looking at it stirs something\ndeep in your chest.',
    'events.vein_lord.say': ['The vein on the north wall gave a great pulse.', 'Crystals gather together into the\nshape of a stone giant, and slowly\nrise to their feet...!'],
    'events.vein_lord.i.choose': ['Stand and fight', 'Turn back'],
    'events.vein_lord.i.choose.text': 'Fight the Lord of the Vein?\n(A very powerful foe)',
    'events.vein_lord.say_2': 'The party quietly backed away.\nThe Lord of the Vein melted back\ninto the wall.',
    'events.vein_lord.say_3': ['The Lord of the Vein crumbled\nback into scattered crystals.', 'In a grotto at the back of the hall,\nsomething is glowing.'],
    // ---- src/events/mine_trolley.js
    'ev.mine_trolley.COURSES.0.label': 'Beginner: Upper Tunnels',
    'ev.mine_trolley.COURSES.1.label': 'Intermediate: Deep Shafts Main Line',
    'ev.mine_trolley.COURSES.2.label': 'Advanced: Descent to the Seventh Level',
    'ev.mine_trolley.SEG.j.title': 'Junction',
    'ev.mine_trolley.SEG.j.intro': 'A junction! Pull the lever\nfor the shortcut track!',
    'ev.mine_trolley.SEG.j.ok': 'Clank! Onto the shortcut!',
    'ev.mine_trolley.SEG.j.ng': 'Too slow on the lever... the long way round!',
    'ev.mine_trolley.SEG.c.title': 'Sharp Curve',
    'ev.mine_trolley.SEG.c.intro': 'Sharp curve ahead!\nBrake!',
    'ev.mine_trolley.SEG.c.ok': 'Screeech... Made the turn!',
    'ev.mine_trolley.SEG.c.ng': 'Braked too late!\nThe wheels lift, and you lose speed...!',
    'events.dovan_race_keeper.say': ['Want to enter the cart race?\nFrom the station down the mine rails.\nBeat the old record and you win.', 'At a junction, pull the lever for\nthe shortcut. Before a curve, brake.\nBe late, and detours and slowdowns cost you.'],
    'events.dovan_race_keeper.labels': ' (Won)',
    'events.dovan_race_keeper.i.choose.0': 'Leave',
    'events.dovan_race_keeper.i.choose.text': 'Which line will you run?',
    'events.dovan_race_keeper.say_2': 'Win the lower course first.',
    'events.dovan_race_keeper.say_3': '{label}. The record is {record} seconds.\nIn you get!',
    'events.dovan_race_keeper.caption': 'Clunk... clunk, clunk-clunk-clunk...!\nThe cart rolls down the mine rails.',
    'events.dovan_race_keeper.r.title': 'Cart Race: {title} ({p1}/{n})',
    'events.dovan_race_keeper.caption_2': 'Finish! {time} seconds.',
    'events.dovan_race_keeper.say_4': 'You were {p0} seconds off the record.\nCome try again anytime.',
    'events.dovan_race_keeper.say_5': 'Broke the record again. Nice.',
    'events.dovan_race_keeper.say_6': 'Not late once! Masterful.',
    'events.dovan_race_keeper.say_7': 'You did it, a new record!\n{label} is yours.\nHere\'s your prize.',
    'events.dovan_race_keeper.say_8': 'Nobody\'s won the advanced course in ten years.\nThat bell marks you as a master cart rider.',
  });
})(window.RPG);
